from __future__ import annotations

from pydantic import Field
from typing_extensions import TypedDict

from ..core import RFC3339DateTime, SdkBaseModel
from .amount110 import Amount110, Amount110Dict
from .counterparty11 import Counterparty11, Counterparty11Dict


class PaymentDetails1(SdkBaseModel):
    amount: Amount110
    """The amount of the payment."""

    counterparty: Counterparty11
    """Contains information about the party that receives the payment funds."""

    description: str
    """The description for the payment. It is generated by the payment method, such as iDEAL, and should be shown to the
    user."""

    expires_at: RFC3339DateTime = Field(alias="expiresAt")
    """The expiration date of the payment in ISO DateTime format, as described on ISO 20022
    (YYYY-MM-DDThh:mm:ss.sss+/-hh:mm).

    Example: **2025-12-30T14:15:30+01:00**"""


class PaymentDetails1Dict(TypedDict):
    amount: Amount110 | Amount110Dict
    counterparty: Counterparty11 | Counterparty11Dict
    description: str
    expires_at: RFC3339DateTime
